// Phase 6 - extrae y valida el contexto del dispatch real de N8nWebhookDispatcher.
// Contrato exacto (packages/infrastructure/src/n8n/n8n-webhook-dispatcher.ts):
//   { executionId, organizationId, automationId, clientId, idempotencyKey,
//     triggerType, callbackUrl, metadata }
// 'attempt' normalmente NO viene en el payload de dispatch real (se asume 1),
// pero se lee de source.attempt si algun caller de prueba lo informa.
//
// HALLAZGO (lectura del body del Webhook) -- corregido:
// El nodo Webhook 'Recibe Dispatch' entrega el payload HTTP dentro de
// $json.body (junto a headers/params/query), pero leer $json.body de forma
// directa es fragil: $json es un alias de conveniencia que puede no
// resolver de forma fiable dentro de un Code node segun el modo de
// ejecucion/version de n8n. Evidencia real observada: 'Recibe Dispatch'
// recibia correctamente body.callbackUrl, pero 'Extraer Dispatch' producia
// callbackUrl vacio y validationError "callbackUrl no es una URL valida".
// Correccion: usar $json directamente (alias estable del item actual en
// modo runOnceForEachItem -- $input.first() NO es valido en este modo,
// n8n lanza "Can't use .first() here") y aceptar tanto el envelope anidado
// del Webhook node ({headers,params,query,body}) como un payload ya plano
// (sin envelope), para pruebas manuales/futuras variantes de n8n:
//   const envelope = $json;
//   const source = envelope.body ?? envelope;

const envelope = $json;
const source = envelope.body ?? envelope;

const organizationId = typeof source.organizationId === 'string' ? source.organizationId : '';
const executionId = typeof source.executionId === 'string' ? source.executionId : '';
const automationId = typeof source.automationId === 'string' ? source.automationId : '';
const idempotencyKey = typeof source.idempotencyKey === 'string' ? source.idempotencyKey : '';

// attempt: entero >= 1 si source lo informa (source.attempt); si no, 1.
const rawAttempt = source.attempt;
const attempt = (typeof rawAttempt === 'number' && Number.isInteger(rawAttempt) && rawAttempt >= 1)
  ? rawAttempt
  : 1;

// fixtureMode: primero source.fixtureMode (top-level); si no existe,
// unicamente source.metadata?.fixtureMode. Whitelist explicita de 6
// valores -- cualquier otro valor (incluido ausente/null/typo) cae a
// 'success'.
const ALLOWED_FIXTURE_MODES = ['success', 'failed', 'duplicate', 'stale-timestamp', 'invalid-signature', 'timeout'];
const rawFixtureMode = (typeof source.fixtureMode !== 'undefined' && source.fixtureMode !== null)
  ? source.fixtureMode
  : (source.metadata && source.metadata.fixtureMode);
const fixtureMode = ALLOWED_FIXTURE_MODES.includes(rawFixtureMode) ? rawFixtureMode : 'success';

// Validacion deterministica por regex -- NO usar new URL(): el task runner
// de n8n (modo aislado de ejecucion de nodos Code) no expone el global URL,
// y el catch de un new URL() fallido se confundia con un formato invalido
// ("callbackUrl no es una URL valida") incluso para URLs correctas.
// Acepta EXCLUSIVAMENTE http, uno de los 3 hosts locales permitidos, un
// puerto numerico, y el path fijo /api/webhooks/n8n -- sin query string,
// sin fragment, sin path adicional, sin otros protocolos.
const CALLBACK_URL_PATTERN = /^http:\/\/(localhost|127\.0\.0\.1|host\.docker\.internal):([0-9]{1,5})\/api\/webhooks\/n8n$/;
const rawCallbackUrl = typeof source.callbackUrl === 'string' ? source.callbackUrl.trim() : '';

let callbackUrl = '';
let validationError = '';

if (!executionId) {
  validationError = 'executionId es requerido';
} else if (!organizationId) {
  validationError = 'organizationId es requerido';
} else if (!automationId) {
  validationError = 'automationId es requerido';
} else if (!rawCallbackUrl) {
  validationError = 'callbackUrl es requerido';
} else {
  const match = CALLBACK_URL_PATTERN.exec(rawCallbackUrl);
  if (!match) {
    validationError = 'callbackUrl no cumple el formato permitido (http://localhost|127.0.0.1|host.docker.internal:<puerto>/api/webhooks/n8n)';
  } else {
    const matchedHost = match[1];
    const port = match[2];
    // Solo en local: el contenedor de n8n no resuelve 'localhost' al host
    // que corre Next.js, asi que se reescribe a host.docker.internal.
    // 127.0.0.1 y host.docker.internal se dejan tal cual. El path
    // (/api/webhooks/n8n) es fijo por la propia regex.
    const normalizedHost = matchedHost === 'localhost' ? 'host.docker.internal' : matchedHost;
    callbackUrl = `http://${normalizedHost}:${port}/api/webhooks/n8n`;
  }
}

return {
  json: {
    organizationId,
    executionId,
    automationId,
    idempotencyKey,
    attempt,
    callbackUrl,
    fixtureMode,
    validationError,
  },
};

// Phase 6 - firma HMAC compatible con apps/web/src/lib/webhooks/hmac.ts
// canonical = `${unixTs}.${rawBody}` ; signature = hex(HMAC_SHA256(secret, canonical))
// rawBody es EXACTAMENTE lo que se transmite (no se reserializa despues de firmar).
//
// HALLAZGO (perdida de contexto) -- corregido: este nodo YA NO lee
// $input.item.json. En las ramas Success/Failed/Duplicate, el nodo HTTP
// 'Enviar ...' anterior ya se ejecuto y su salida reemplaza el item por la
// respuesta HTTP (sin executionId ni callbackUrl). El contexto se toma
// siempre de 'Extraer Dispatch' por nombre, que n8n vincula por paired item
// sin importar cuantos nodos HTTP se ejecutaron entre medio.

const crypto = require('crypto');
const secret = $env.AUTOMATION_WEBHOOK_SECRET;
if (!secret || secret.length < 32) {
  throw new Error('AUTOMATION_WEBHOOK_SECRET no configurado o muy corto (n8n-local/.env)');
}

const ctx = $('Extraer Dispatch').item.json;
if (!ctx.executionId) {
  throw new Error('[fixture] executionId ausente en el contexto - no se puede firmar el callback');
}
if (!ctx.callbackUrl) {
  throw new Error('[fixture] callbackUrl ausente en el contexto - no se puede enviar el callback');
}

const unixTs = Math.floor(Date.now() / 1000).toString();

const callbackBody = {
  eventId: `${ctx.executionId}-${unixTs}-started`,
  eventType: 'execution.started',
  timestamp: new Date().toISOString(),
  organizationId: ctx.organizationId,
  executionId: ctx.executionId,
  automationId: ctx.automationId,
  attempt: ctx.attempt,
  outputMetadata: null,
  errorCode: null,
  errorMessage: null,
};

const rawBody = JSON.stringify(callbackBody);
const canonical = `${unixTs}.${rawBody}`;
const signature = crypto.createHmac('sha256', Buffer.from(secret, 'utf-8'))
  .update(canonical, 'utf-8')
  .digest('hex');

return {
  json: {
    executionId: ctx.executionId,
    automationId: ctx.automationId,
    organizationId: ctx.organizationId,
    callbackUrl: ctx.callbackUrl,
    url: ctx.callbackUrl,
    fixtureMode: ctx.fixtureMode,
    eventId: callbackBody.eventId,
    unixTs,
    rawBody,
    signature,
  },
};

